template <typename N>
typename Earcut<N>::Node* Earcut<N>::insertNode(N i, double x, double y, Node* last) {
    Node* p = nodes.construct(i, x, y);

    if (!last) {
        p->prev = p;
        p->next = p;

    } else {
        assert(last);
        p->next = last->next;
        p->prev = last;
        last->next->prev = p;
        last->next = p;
    }
    return p;
}

