fn run(&mut self, points: &[Vec<[f64;2]>]) {
    if points.is_empty() { return; }
    let mut threshold: i32 = 80;
    let mut len: usize = 0;
    let mut i = 0;
    while threshold >= 0 && i < points.len() {
        threshold -= points[i].len() as i32;
        len += points[i].len();
        i += 1;
    }

    let outer = self.linked_list(&points[0], true);
    let mut outer_node = match outer {
        Some(o) => o,
        None => return,
    };
    if self.nodes[outer_node].prev == self.nodes[outer_node].next { return; }

    if points.len() > 1 {
        outer_node = self.eliminate_holes(points, outer_node);
    }

    self.hashing = threshold < 0;
    if self.hashing {
        let mut p = self.nodes[outer_node].next;
        self.min_x = self.nodes[outer_node].x;
        self.max_x = self.nodes[outer_node].x;
        self.min_y = self.nodes[outer_node].y;
        self.max_y = self.nodes[outer_node].y;
        loop {
            let x = self.nodes[p].x;
            let y = self.nodes[p].y;
            if x < self.min_x { self.min_x = x; }
            if y < self.min_y { self.min_y = y; }
            if x > self.max_x { self.max_x = x; }
            if y > self.max_y { self.max_y = y; }
            p = self.nodes[p].next;
            if p == outer_node { break; }
        }
        let mut inv = f64::max(self.max_x - self.min_x, self.max_y - self.min_y);
        inv = if inv != 0.0 { 32767.5 / inv } else { 0.0 };
        self.inv_size = inv;
    }

    self.earcut_linked(Some(outer_node), 0);
}
```

