linked_list:

```rust
fn linked_list(&mut self, points: &[[f64;2]], clockwise: bool) -> Option<usize> {
    let mut sum = 0.0f64;
    let len = points.len();
    let mut last: Option<usize> = None;

    let mut i = 0usize;
    let mut j = if len > 0 { len - 1 } else { 0 };
    while i < len {
        let p1 = points[i];
        let p2 = points[j];
        sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
        j = i;
        i += 1;
    }

    if clockwise == (sum > 0.0) {
        for i in 0..len {
            last = Some(self.insert_node(self.vertices + i as u32, points[i][0], points[i][1], last));
        }
    } else {
        let mut i = len;
        while i > 0 {
            last = Some(self.insert_node(self.vertices + (i - 1) as u32, points[i-1][0], points[i-1][1], last));
            i -= 1;
        }
    }

    if let Some(l) = last {
        if self.equals(l, self.nodes[l].next) {
            self.remove_node(l);
            last = Some(self.nodes[l].next);
        }
    }

    self.vertices += len as u32;
    last
}
```

Note: `vertices + i` where vertices is u32 — in C++ N is uint32_t. Fine.

