fn find_hole_bridge(&mut self, hole: usize, outer_node: usize) -> Option<usize> {
    let mut p = outer_node;
    let hx = self.nodes[hole].x;
    let hy = self.nodes[hole].y;
    let mut qx = f64::NEG_INFINITY;
    let mut m: Option<usize> = None;
    loop {
        if hy <= self.nodes[p].y && hy >= self.nodes[self.nodes[p].next].y && self.nodes[self.nodes[p].next].y != self.nodes[p].y {
            let px = self.nodes[p].x;
            let py_ = self.nodes[p].y;
            let nx = self.nodes[self.nodes[p].next].x;
            let ny = self.nodes[self.nodes[p].next].y;
            let x = px + (hy - py_) * (nx - px) / (ny - py_);
            if x <= hx && x > qx {
                qx = x;
                if x == hx {
                    if hy == py_ { return Some(p); }
                    if hy == ny { return Some(self.nodes[p].next); }
                }
                m = Some(if px < nx { p } else { self.nodes[p].next });
            }
        }
        p = self.nodes[p].next;
        if p == outer_node { break; }
    }
    let mut m = m?;
    if hx == qx { return Some(m); }
    let stop = m;
    let mut tan_min = f64::INFINITY;
    let mx = self.nodes[m].x;
    let my = self.nodes[m].y;
    let mut p = m;
    loop {
        if hx >= self.nodes[p].x && self.nodes[p].x >= mx && hx != self.nodes[p].x
            && self.point_in_triangle(
                if hy < my { hx } else { qx }, hy,
                mx, my,
                if hy < my { qx } else { hx }, hy,
                self.nodes[p].x, self.nodes[p].y) {
            let tan_cur = f64::abs(hy - self.nodes[p].y) / (hx - self.nodes[p].x);
            if self.locally_inside(p, hole)
                && (tan_cur < tan_min || (tan_cur == tan_min && (self.nodes[p].x > self.nodes[m].x || self.sector_contains_sector(m, p)))) {
                m = p;
                tan_min = tan_cur;
            }
        }
        p = self.nodes[p].next;
        if p == stop { break; }
    }
    Some(m)
}
