// C atoi semantics (glibc): atoi is (int)strtol(s, NULL, 10) — skip leading
// whitespace, optional sign, parse digits, stop at first non-digit, 0 when no
// digits, saturate to LONG_MAX/LONG_MIN on overflow, then truncate to int.
fn atoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut i = 0usize;
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        neg = b[i] == b'-';
        i += 1;
    }
    let mut val: i64 = 0;
    let mut overflow = false;
    while i < b.len() && b[i].is_ascii_digit() {
        let d = (b[i] - b'0') as i64;
        match val.checked_mul(10).and_then(|v| v.checked_add(d)) {
            Some(v) => val = v,
            None => overflow = true,
        }
        i += 1;
    }
    if overflow {
        return if neg { i64::MIN as i32 } else { i64::MAX as i32 };
    }
    let val = if neg { -val } else { val };
    val as i32
}
